p = os.path.join(d, 'dense.bin')
f = open(p, 'wb'); f.write(b'x' * (8 * 2**20)); f.close()
print('dense usage', w.disk_usage(p))
print('flag', w.sparse_flag(p, True))
print('after flag usage', w.disk_usage(p))
print('after flag ranges', w.allocated_ranges(p))
# F: directory
for fn in (w.disk_usage, w.allocated_ranges, w.sparse_state):
    try:
        fn(d); print(fn.__name__, 'NO RAISE')
    except w.WSParseError as e:
        print(fn.__name__, e.kind)
try:
    w.sparse_flag(d, True)
except w.WSParseError as e:
    print('sparse_flag', e.kind)
try:
    w.preallocate(d, 1024)
except w.WSParseError as e:
    print('preallocate', e.kind)
